    /\ munch [(T + 3168, T + 3169); (2966856, 2966860); (2383040, 2911472); (bv_unsigned sp - 2288, bv_unsigned sp)]%Z m m'
    /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ ia_state true m' /\ rw_cells asegs m' (T + 3168) [C1 (Z_to_bv 8 0)]
    /\ stk asegs m' lo (bv_unsigned sp).

